  3840→    const num = parseInt(target, 10);
  3841→    if (isNaN(num) || num < 0) { el.textContent = target; return; }
  3842→    const duration = 600;
  3843→    const step = 14;
  3844→    const increment = Math.max(1, num / (duration / step));
  3845→    let current = 0;
  3846→    clearInterval(el._countTimer);
  3847→    el._countTimer = setInterval(function() {
  3848→        current += increment;
